document.body.insertAdjacentHTML('beforeend','<div id="authOverlay" class="auth-overlay"><div class="auth-card"><h2>LVL - NetAtlas</h2><p class="muted">Entre para acessar o mapa da rede.</p><form id="loginForm"><label>Usuário</label><input id="loginUser" autocomplete="username" required><label>Senha</label><input id="loginPassword" type="password" autocomplete="current-password" required><p id="loginError" class="form-error"></p><button class="primary" type="submit">Entrar</button></form></div></div>');

api=async function(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json'},...opt});if(r.status===401){showLogin();throw Error('Sessão expirada')}if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail||r.statusText))}return r.status===204?null:r.json()};
function showLogin(){document.getElementById('authOverlay').style.display='grid';document.getElementById('loginPassword').value='';document.getElementById('loginUser').focus()}
document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();let error=document.getElementById('loginError');error.textContent='Entrando…';let r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('loginUser').value,password:document.getElementById('loginPassword').value})});if(!r.ok){let x=await r.json().catch(()=>({}));error.textContent=x.detail||'Não foi possível entrar';return}location.reload()};
document.getElementById('logoutButton').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location.reload()};
function canOperate(){return netUser&&['superadmin','admin'].includes(netUser.role)}
function canReport(){return netUser&&netUser.role!=='viewer'}
function roleName(role){return({superadmin:'Superadmin',admin:'Admin',technician:'Técnico',viewer:'Visualização'})[role]||role}
function applyRole(){document.body.classList.add(`role-${netUser.role}`);document.getElementById('authOverlay').style.display='none';document.getElementById('account').textContent=`${netUser.display_name} · ${roleName(netUser.role)}`;document.getElementById('logoutButton').style.display='inline-block';document.getElementById('issuesButton').style.display='inline-block';document.getElementById('continuousButton').style.display='inline-block';if(canOperate()){document.getElementById('manageMenu').style.display='inline-block';document.getElementById('settingsMenu').style.display='inline-block'}let hidden=netUser.role==='superadmin'?[]:netUser.role==='admin'?['auditButton','sessionsButton','licenseButton']:['auditButton','usersButton','sessionsButton','licenseButton'];for(let id of hidden)document.getElementById(id)?.remove();if(netUser.role!=='superadmin')document.querySelectorAll('.leaflet-draw').forEach(control=>control.remove())}

map.getContainer().addEventListener('contextmenu',event=>{if(netUser&&!canOperate()){event.preventDefault();event.stopImmediatePropagation()}},true);

const originalRefreshMarkers=refreshMarkers;
map.off('zoomend',originalRefreshMarkers);
refreshMarkers=function(){let z=map.getZoom(),popView=z<=15;for(let m of markers.values()){let hide=m.net.kind==='device'?popView:m.net.kind==='cto'?z<16:m.net.kind==='dedicated'?z<13:m.net.kind==='cloud'?z<14:false;if(hide){if(map.hasLayer(m))map.removeLayer(m)}else{m.setIcon(mkIcon(m.net));if(!map.hasLayer(m))m.addTo(map)}}siteMarkers.forEach(m=>{if(popView){if(!map.hasLayer(m))m.addTo(map)}else if(map.hasLayer(m))map.removeLayer(m)});refreshIssueVisibility()};
map.on('zoomend',refreshMarkers);
map.on('zoomend',renderOperatorCards);map.on('moveend',renderOperatorCards);

function popMarkerIcon(site,severity=null){let label=site.name.replace(/^CENTRAL\s+/i,''),color=severity==='medium'?'#fde047':severity==='severe'?'#fb923c':severity?'#ff2020':null,alert=color?`<i class="pop-alert-dot" style="--alert-color:${color}" title="Alerta próximo a este POP"></i>`:'';return L.divIcon({className:'',iconSize:[118,58],iconAnchor:[59,29],html:`<div class="pop-marker"><b>POP</b><span>${esc(label)}</span><small>${site.devices.length} host${site.devices.length===1?'':'s'}</small>${alert}</div>`})}
loadTopology=async function(){for(let[k,m]of markers)if(k.startsWith('device:')){map.removeLayer(m);markers.delete(k)}siteMarkers.splice(0).forEach(m=>map.removeLayer(m));let data=await api('/api/topology'),bounds=[],count=0;data.sites.forEach(s=>{bounds.push([s.latitude,s.longitude]);s.devices.forEach((d,i)=>{count++;d.kind='device';d.pop_id=s.id;d.pop_name=s.name;d.pop_latitude=s.latitude;d.pop_longitude=s.longitude;d.down=d.zabbix_hostid&&Number(d.availability)===2;d.planned=d.netbox_status==='planned';let atPop=d.latitude==null||d.longitude==null||(Math.abs(Number(d.latitude)-Number(s.latitude))<.000001&&Math.abs(Number(d.longitude)-Number(s.longitude))<.000001),p=atPop?offset(s.latitude,s.longitude,i,s.devices.length):[d.latitude,d.longitude];addMarker(d,p)});let label=s.name.replace(/^CENTRAL\s+/i,''),sm=L.marker([s.latitude,s.longitude],{icon:popMarkerIcon(s),title:`POP ${label}`});sm.net=s;sm.on('click',()=>map.setView([s.latitude,s.longitude],16));siteMarkers.push(sm)});if(bounds.length)map.fitBounds(bounds,{padding:[50,50]});document.getElementById('summary').textContent=`${data.sites.length} POPs · ${count} equipamentos`;await loadNodes();refreshMarkers()};

const originalStartMove=startMove,originalBeginLink=beginLink,originalChooseElementAt=chooseElementAt;
startMove=function(m){if(!canOperate()){hint('Seu perfil permite somente visualizar e reportar erros.');return}originalStartMove(m)};
beginLink=function(m,x){if(!canOperate()){hint('Seu perfil não permite criar enlaces.');return}return originalBeginLink(m,x)};
chooseElementAt=function(p){if(!canOperate()){hint('Seu perfil não permite adicionar elementos.');return}originalChooseElementAt(p)};
const originalAddMarker=addMarker;
addMarker=function(d,point){let m=originalAddMarker(d,point);if(d.kind==='cto'||d.kind==='device'){m.off('contextmenu');m.on('contextmenu',e=>{L.DomEvent.stopPropagation(e);if(mode)return;let isHost=d.kind==='device',canDelete=canOperate(),label=isHost?'Host':'CTO',p=L.popup().setLatLng(e.latlng).setContent(`<div class="link-menu"><b>${esc(d.name)}</b>${canOperate()?'<button id="moveElement">Mover</button>':''}${canDelete?`<button id="deleteElementHere" class="danger">Excluir ${label}</button>`:''}</div>`).openOn(map);setTimeout(()=>{let move=document.getElementById('moveElement'),remove=document.getElementById('deleteElementHere');if(move)move.onclick=()=>{map.closePopup(p);startMove(m)};if(remove)remove.onclick=()=>{map.closePopup(p);isHost?deleteHostConfirmed(m):deleteCtoConfirmed(m)}},0)})}return m};

function reportButton(target){let old=document.getElementById('reportIssue');if(old)old.remove();if(!canReport())return;let b=document.createElement('button');b.id='reportIssue';b.className='panel-action';b.textContent='Reportar erro';b.onclick=()=>openIssueForm(target);let dialog=document.getElementById('linkDialog'),container=dialog&&dialog.classList.contains('show')?document.getElementById('linkDialogBody'):document.getElementById('panelBody');container.append(b)}
const originalOpenHostPanel=openHostPanel;
function bgpState(value){return({1:'Idle',2:'Connect',3:'Active',4:'OpenSent',5:'OpenConfirm',6:'Established'})[Number(value)]||'Desconhecido'}
function bgpUptime(seconds){let n=Number(seconds);if(!Number.isFinite(n)||n<=0)return'—';let d=Math.floor(n/86400),h=Math.floor(n%86400/3600),m=Math.floor(n%3600/60);return`${d?`${d}d `:''}${h}h ${m}min`}
function operatorIdentity(iface){return Number(iface.status_itemid||iface.rx_itemid||iface.tx_itemid||0)}
function operatorAssignmentForm(configured,current=null){let names=[...new Set(configured.map(x=>x.provider_name))].sort((a,b)=>a.localeCompare(b,'pt-BR'));closeModal();return new Promise(resolve=>{pendingForm=resolve;modal(current?'Editar interface da operadora':'Vincular interface a uma operadora',`<form id="operatorAssignment"><label>Operadora</label><select id="operatorExisting"><option value="__new__">Criar nova operadora</option>${names.map(name=>`<option value="${esc(name)}">Adicionar à ${esc(name)}</option>`).join('')}</select><div id="newOperatorWrap"><label>Nome da operadora</label><input id="newOperatorName" maxlength="120" autocomplete="off" value="${esc(current?.provider_name||'')}"></div><label>Subtítulo desta interface</label><input id="operatorSubtitle" maxlength="160" autocomplete="off" placeholder="Ex.: Link principal · 10 Gbps" value="${esc(current?.subtitle||'')}"><label>Família de endereçamento</label><select id="operatorFamily"><option value="ipv4">IPv4</option><option value="ipv6">IPv6</option><option value="dual">IPv4 e IPv6</option></select><p id="operatorAssignmentError" class="form-error"></p><button class="primary" type="submit">Salvar vínculo</button></form>`);let existing=document.getElementById('operatorExisting'),wrap=document.getElementById('newOperatorWrap');if(current&&names.includes(current.provider_name))existing.value=current.provider_name;existing.onchange=()=>wrap.style.display=existing.value==='__new__'?'block':'none';existing.onchange();document.getElementById('operatorFamily').value=current?.address_family||'ipv4';document.getElementById('operatorAssignment').onsubmit=e=>{e.preventDefault();let provider=existing.value==='__new__'?document.getElementById('newOperatorName').value.trim():existing.value;if(!provider){document.getElementById('operatorAssignmentError').textContent='Informe o nome da operadora.';return}resolveForm({provider_name:provider,address_family:document.getElementById('operatorFamily').value,subtitle:document.getElementById('operatorSubtitle').value.trim()||null})}})}
async function configureOperatorInterfaces(m,body){let [configured,xs]=await Promise.all([api(`/api/devices/${m.net.id}/bgp/operator-interfaces`),api(`/api/interfaces/${m.net.zabbix_hostid}`)]),byItem=new Map(configured.map(x=>[Number(x.interface_itemid),x]));async function save(iface,item,current=null){let assignment=await operatorAssignmentForm(configured,current);if(!assignment)return;await api(`/api/devices/${m.net.id}/bgp/operator-interfaces`,{method:'PUT',body:JSON.stringify({zabbix_hostid:Number(m.net.zabbix_hostid),interface_itemid:item,interface_name:iface.name,interface_description:iface.description||null,...assignment})});await loadOperatorCards();await openHostPanel(m);flashHint(current?'Interface da operadora atualizada.':'Interface vinculada à operadora.')}[...body.querySelectorAll('#panelIfaces .panel-iface')].forEach(card=>{let iface=xs[Number(card.dataset.i)],item=operatorIdentity(iface);if(!iface||!item)return;let current=byItem.get(item),details=card.querySelector('.iface-details');if(!details)return;let edit=document.createElement('button');edit.className='panel-action operator-action';edit.textContent=current?`Editar operadora · ${current.provider_name}${current.subtitle?` · ${current.subtitle}`:''}`:'Marcar como Operadora';edit.onclick=async e=>{e.stopPropagation();try{await save(iface,item,current)}catch(error){flashHint(error.message,5000)}};details.append(edit);if(current){let remove=document.createElement('button');remove.className='panel-action operator-action operator-remove';remove.textContent='Remover vínculo de operadora';remove.onclick=async e=>{e.stopPropagation();let ok=await confirmForm('Remover interface de operadora',`Remover ${current.provider_name} da interface ${iface.name}?`,'Remover');if(!ok)return;try{await api(`/api/operator-interfaces/${current.id}`,{method:'DELETE'});await loadOperatorCards();await openHostPanel(m);flashHint('Interface removida das operadoras.')}catch(error){flashHint(error.message,5000)}};details.append(remove);let label=document.createElement('label');label.className='operator-upload';label.innerHTML=`${current.image_url?'Substituir':'Adicionar'} foto da operadora<input type="file" accept="image/png,image/jpeg,image/webp,image/gif">`;label.onclick=e=>e.stopPropagation();label.querySelector('input').onchange=async e=>{e.stopPropagation();let file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){flashHint('A imagem deve possuir no máximo 2 MB.',5000);return}try{await api(`/api/operator-interfaces/${current.id}/image`,{method:'PUT',headers:{'Content-Type':file.type},body:file});await loadOperatorCards();await openHostPanel(m);flashHint('Foto da operadora atualizada.')}catch(error){flashHint(error.message,5000)}};details.append(label)}})}
function groupedOperators(group){let providers=new Map();for(let item of group.interfaces){let key=item.provider_name.toLocaleLowerCase('pt-BR');if(!providers.has(key))providers.set(key,{name:item.provider_name,image:item.image_url,interfaces:[]});let provider=providers.get(key);if(!provider.image&&item.image_url)provider.image=item.image_url;provider.interfaces.push(item)}return[...providers.values()]}
