async function saveOperatorCloud(provider,latlng){await api('/api/nodes',{method:'POST',body:JSON.stringify({name:provider.name,kind:'cloud',latitude:latlng.lat,longitude:latlng.lng})});pendingOperatorPosition=null;cancel();await loadNodes();refreshCloudProviders();map.setView(latlng,Math.max(map.getZoom(),15));flashHint(`${provider.name} adicionada ao mapa.`,5000)}
function operatorCoordinatesForm(provider){modal(`Adicionar ${provider.name}`,`<form id="operatorCoordinatesForm"><label>Latitude</label><input id="operatorLatitude" type="number" step="any" required><label>Longitude</label><input id="operatorLongitude" type="number" step="any" required><p id="operatorCoordinatesError" class="form-error"></p><button class="primary">Adicionar nuvem</button></form>`);document.getElementById('operatorCoordinatesForm').onsubmit=async event=>{event.preventDefault();try{await saveOperatorCloud(provider,L.latLng(Number(document.getElementById('operatorLatitude').value),Number(document.getElementById('operatorLongitude').value)))}catch(error){document.getElementById('operatorCoordinatesError').textContent=error.message}}}
function addOperatorToMap(){let providers=providerCatalog(),placed=new Set([...markers.values()].filter(marker=>marker.net.kind==='cloud').map(marker=>marker.net.name.toLocaleLowerCase('pt-BR'))),available=providers.filter(provider=>!placed.has(provider.name.toLocaleLowerCase('pt-BR')));modal('Adicionar operadora ao mapa',available.length?`<p>Escolha uma operadora já cadastrada nas interfaces.</p>${available.map((provider,index)=>`<button class="iface choose-map-operator" data-index="${index}"><b>${esc(provider.name)}</b><br><small>${provider.interfaces.length} interface${provider.interfaces.length===1?'':'s'} cadastrada${provider.interfaces.length===1?'':'s'}</small></button>`).join('')}`:'<p class="muted">Todas as operadoras cadastradas já estão no mapa, ou ainda não há operadoras vinculadas às interfaces.</p>');document.querySelectorAll('.choose-map-operator').forEach(button=>button.onclick=()=>{let provider=available[Number(button.dataset.index)];modal(`Posicionar ${provider.name}`,`<button id="operatorPlaceMap" class="iface"><b>Posicionar no mapa</b><br><small>Clique no ponto onde a nuvem deve aparecer.</small></button><button id="operatorPlaceCoordinates" class="iface"><b>Informar coordenadas</b></button>`);document.getElementById('operatorPlaceMap').onclick=()=>{closeModal();pendingOperatorPosition=provider;mode='operator-position';document.getElementById('cancel').style.display='inline-block';hint(`Clique no mapa para posicionar a operadora ${provider.name}.`)};document.getElementById('operatorPlaceCoordinates').onclick=()=>operatorCoordinatesForm(provider)})}
document.getElementById('addOperatorMapButton').onclick=()=>addOperatorToMap();
map.on('click',event=>{if(mode!=='operator-position'||!pendingOperatorPosition)return;let provider=pendingOperatorPosition;saveOperatorCloud(provider,event.latlng).catch(error=>{mode='operator-position';pendingOperatorPosition=provider;flashHint(error.message,6000)})});
function openOperatorCloud(m){let provider=m.net.provider||providerCatalog().find(item=>item.name.toLocaleLowerCase('pt-BR')===m.net.name.toLocaleLowerCase('pt-BR'));if(!provider){showPanel(`<h2>${esc(m.net.name)}</h2><p class="muted">Operadora ainda sem interfaces vinculadas.</p>`);return}showPanel(`<h2>${esc(provider.name)}</h2><div class="panel-meta">Operadora · ${provider.interfaces.length} interface${provider.interfaces.length===1?'':'s'}</div><div class="operator-cloud-info">${provider.interfaces.map(item=>{let metrics=item.metrics||{},state=metrics.status||'unknown';return`<article class="operator-cloud-provider"><h3>${esc(item.subtitle||item.interface_name)}</h3><small>${esc(item.interface_name)} · ${esc(item.address_family==='dual'?'IPv4 e IPv6':item.address_family.toUpperCase())}</small><b class="${state==='up'?'updot':state==='down'?'downdot':'unkdot'}">● ${esc(statusText(state))}</b><small>Download ${esc(formatRate(metrics.download))} · Upload ${esc(formatRate(metrics.upload))}</small></article>`}).join('')}</div>${canOperate()?`<label class="operator-upload">${provider.image_url?'Substituir':'Adicionar'} logo da operadora<input id="operatorCloudLogo" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><button id="operatorCloudLink" class="panel-action">Criar enlace para esta operadora</button><button id="moveOperatorCloud" class="panel-action">Mover no mapa</button>`:''}`);let upload=document.getElementById('operatorCloudLogo');if(upload)upload.onchange=async event=>{let file=event.target.files[0];if(!file)return;if(file.size>2*1024*1024){flashHint('A imagem deve possuir no máximo 2 MB.',5000);return}try{await api(`/api/operator-interfaces/${provider.interfaces[0].id}/image`,{method:'PUT',headers:{'Content-Type':file.type},body:file});await loadOperatorCards();openOperatorCloud(m);flashHint('Logo da operadora atualizada.',5000)}catch(error){flashHint(error.message,6000)}};let link=document.getElementById('operatorCloudLink');if(link)link.onclick=()=>beginLink(m,null);let move=document.getElementById('moveOperatorCloud');if(move)move.onclick=()=>startMove(m)}

function continuousAlertStops(){let stops=[],seen=new Set();for(let issue of currentIssues.filter(item=>item.status!=='resolved')){let point=null,bounds=null;if(issue.target_kind==='link'){let link=links.find(item=>Number(item.id)===Number(issue.target_id));if(link){seen.add(`link:${link.id}`);if(issue.latitude!=null&&issue.longitude!=null)point=L.latLng(Number(issue.latitude),Number(issue.longitude));else{bounds=L.latLngBounds((link.display_coordinates||link.geometry.coordinates).map(item=>[item[1],item[0]]));point=linkMidpoint(link.display_coordinates||link.geometry.coordinates)}}}else{let marker=markers.get(`${issue.target_kind==='device'?'device':'cto'}:${issue.target_id}`)||markers.get(`host:${issue.target_id}`);if(marker)point=marker.getLatLng()}if(point)stops.push({type:'alert',name:`${issueLabel(issue.severity)} · ${issue.target_name}`,detail:issue.description,point,bounds})}for(let link of links.filter(item=>item.status==='down')){let key=`link:${link.id}`;if(seen.has(key))continue;let coordinates=link.display_coordinates||link.geometry.coordinates;stops.push({type:'alert',name:`Enlace DOWN · ${link.name}`,detail:`${link.source_name} → ${link.target_name}`,point:linkMidpoint(coordinates),bounds:L.latLngBounds(coordinates.map(item=>[item[1],item[0]]))})}for(let marker of [...markers.values()].filter(item=>item.net.kind==='dedicated'&&dedicatedStatus(item.net.id)==='down')){let metric=dedicatedMetrics.get(Number(marker.net.id));stops.push({type:'alert',name:`Cliente dedicado DOWN · ${marker.net.name}`,detail:`ICMP sem resposta${metric?.loss_percent!=null?` · perda ${Number(metric.loss_percent).toLocaleString('pt-BR',{maximumFractionDigits:2})}%`:''}`,point:marker.getLatLng(),bounds:null})}return stops}
function continuousStops(){let pops=siteMarkers.map(marker=>({name:marker.options.title||'POP',point:marker.getLatLng(),type:'pop'})),alerts=continuousAlertStops(),stops=[];pops.forEach((pop,index)=>{stops.push(pop);alerts.filter((_,alertIndex)=>alertIndex%Math.max(1,pops.length)===index).forEach(alert=>stops.push(alert))});if(pops.length){let bounds=L.latLngBounds(pops.map(item=>item.point));stops.push({name:'Rede inteira',bounds,type:'network'})}return stops}
function continuousAuxDefaultEnabled(){return!matchMedia('(max-width:700px)').matches&&!/(?:;\s*wv\)|LVLNetAtlasApp)/i.test(navigator.userAgent)}
