function destroyContinuousAux(type){let state=continuousAux[type];clearTimeout(state.timer);state.timer=null;if(state.map){state.map.remove();state.map=null}document.getElementById(`continuousAux-${type}`)?.remove();let dock=document.getElementById(`continuousAuxDock-${type}`);if(dock)dock.hidden=false}
