function continuousAuxDeviceIcon(data,label=''){let dedicated=data.kind==='dedicated',size=dedicated?24:26,height=dedicated?24:18,labelHtml=label?`<span class="continuous-aux-device-label">${esc(label)}</span>`:'';return L.divIcon({className:'',iconSize:[size,height],iconAnchor:[size/2,height/2],html:`<div class="continuous-aux-device-wrap"><div class="continuous-aux-device" style="width:${size}px;height:${height}px;max-width:${size}px;max-height:${height}px;overflow:hidden"><img src="${iconUrl(data)}" style="display:block;width:${size}px;height:${height}px;max-width:${size}px;max-height:${height}px;object-fit:contain"></div>${labelHtml}</div>`})}
function runDedicatedAux(){let state=continuousAux.dedicated,panel=document.getElementById('continuousAux-dedicated');if(!continuousActive||!state.map||!panel)return;let items=dedicatedAuxItems(),info=panel.querySelector('.continuous-aux-info'),layer=state.layer;if(!items.length){info.classList.remove('hidden');info.innerHTML='<b>Nenhum cliente dedicado</b><small>Cadastre clientes para iniciar este ciclo.</small>';return}let item=items[state.index%items.length],point=item.marker.getLatLng(),label=item.state==='up'?'Online':item.state==='down'?'Offline':'Sem leitura',metric=dedicatedMetrics.get(Number(item.marker.net.id));layer.clearLayers();item.links.forEach(link=>L.polyline((link.display_coordinates||link.geometry.coordinates).map(p=>[p[1],p[0]]),{color:lineColor(link.status),weight:4,opacity:.9}).addTo(layer));L.marker(point,{icon:L.divIcon({className:'',iconSize:[30,30],iconAnchor:[15,15],html:`<div class="continuous-aux-marker ${item.state}"><img src="/static/icons/company.svg?v=20261006"></div>`})}).addTo(layer);state.map.setView(point,20,{animate:false});info.innerHTML=`<b>${esc(item.marker.net.name)} <span class="continuous-aux-status ${item.state==='up'?'updot':item.state==='down'?'downdot':'unkdot'}">${label}</span></b>${metric?`<small>Perda: ${metric.loss_percent==null?'—':`${Number(metric.loss_percent).toLocaleString('pt-BR',{maximumFractionDigits:2})}%`} · Resposta: ${metric.response_time_ms==null?'—':`${Number(metric.response_time_ms).toLocaleString('pt-BR',{maximumFractionDigits:2})} ms`}</small>`:`<small>${item.links.length} enlace${item.links.length===1?'':'s'} conectado${item.links.length===1?'':'s'}</small>`}`;info.classList.remove('hidden');clearTimeout(state.timer);state.timer=setTimeout(()=>{if(!state.map)return;state.index=(state.index+1)%items.length;runDedicatedAux()},10000)}
function runLinksAux(){let state=continuousAux.links,panel=document.getElementById('continuousAux-links');if(!continuousActive||!state.map||!panel)return;let items=links.filter(link=>!(link.trunk_group&&!link.is_trunk)),info=panel.querySelector('.continuous-aux-info'),layer=state.layer;if(!items.length){info.classList.remove('hidden');info.innerHTML='<b>Nenhum enlace cadastrado</b>';return}let link=items[state.index%items.length],coordinates=link.display_coordinates||link.geometry.coordinates,latlngs=coordinates.map(p=>[p[1],p[0]]),bounds=L.latLngBounds(latlngs),label=statusText(link.status);layer.clearLayers();items.forEach(context=>{let selected=Number(context.id)===Number(link.id),points=(context.display_coordinates||context.geometry.coordinates).map(p=>[p[1],p[0]]);L.polyline(points,{color:lineColor(context.status),weight:selected?6:2.5,opacity:selected?1:.62}).addTo(layer)});for(let marker of markers.values()){if(!['device','host','cto','dedicated','cloud'].includes(marker.net.kind))continue;L.marker(marker.getLatLng(),{icon:continuousAuxDeviceIcon(marker.net),interactive:false}).addTo(layer)}state.map.fitBounds(bounds,{padding:[35,35],maxZoom:20,animate:false});info.innerHTML=`<b>${esc(link.name)} <span class="continuous-aux-status ${link.status==='up'?'updot':link.status==='down'?'downdot':'unkdot'}">${esc(label)}</span></b>`;info.classList.remove('hidden');clearTimeout(state.timer);state.timer=setTimeout(()=>{if(!state.map)return;state.index=(state.index+1)%items.length;runLinksAux()},10000)}
function createContinuousAux(type){if(!continuousActive||continuousAux[type].map)return;if(matchMedia('(max-width:700px)').matches){let other=type==='dedicated'?'links':'dedicated';if(continuousAux[other].map){localStorage.setItem(`netatlas_continuous_${other}`,'0');destroyContinuousAux(other)}}let title=type==='dedicated'?'Clientes dedicados':'Enlaces',icon=type==='dedicated'?'▦':'⇄';document.body.insertAdjacentHTML('beforeend',`<section id="continuousAux-${type}" class="continuous-aux ${type}"><div class="continuous-aux-map"></div><span class="continuous-aux-title">${icon} ${title}</span><button class="continuous-aux-close" title="Fechar painel">×</button><div class="continuous-aux-info"></div></section>`);let panel=document.getElementById(`continuousAux-${type}`),auxMap=L.map(panel.querySelector('.continuous-aux-map'),{zoomControl:false,attributionControl:false,preferCanvas:true,fadeAnimation:false,zoomAnimation:true}).setView(map.getCenter(),map.getZoom());L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,maxNativeZoom:19}).addTo(auxMap);let state=continuousAux[type];state.map=auxMap;state.layer=L.layerGroup().addTo(auxMap);panel.querySelector('.continuous-aux-close').onclick=()=>{localStorage.setItem(`netatlas_continuous_${type}`,'0');destroyContinuousAux(type)};let dock=document.getElementById(`continuousAuxDock-${type}`);if(dock)dock.hidden=true;setTimeout(()=>auxMap.invalidateSize(),50);type==='dedicated'?runDedicatedAux():runLinksAux()}
