function runContinuousStop(advance=false){if(!continuousActive)return;let stops=continuousStops();if(!stops.length){stopContinuousView();flashHint('Cadastre pelo menos um POP para usar a visualização contínua.',5000);return}if(advance)continuousIndex=(continuousIndex+1)%stops.length;let selectedIndex=continuousIndex%stops.length,current=stops[selectedIndex],next=stops[(selectedIndex+1)%stops.length],card=document.getElementById('continuousCard');card.classList.toggle('alert-stop',current.type==='alert');card.innerHTML=`<b>${esc(current.type==='alert'?'⚠ '+current.name:current.name)}</b>${current.detail?`<small>${esc(current.detail)}</small>`:''}<small>Próxima: ${esc(next.name)} · clique para avançar</small>`;clearTimeout(continuousTimer);if(current.type==='network'){map.flyToBounds(current.bounds,{padding:[55,55],duration:2.8});continuousTimer=setTimeout(()=>runContinuousStop(true),60000);return}if(current.type==='alert'){if(current.bounds&&current.bounds.isValid()&&current.bounds.getNorthEast().distanceTo(current.bounds.getSouthWest())>15)map.flyToBounds(current.bounds,{padding:[150,150],maxZoom:20,duration:2.8});else map.flyTo(current.point,20,{animate:true,duration:2.8});continuousTimer=setTimeout(()=>runContinuousStop(true),10000);return}map.flyTo(current.point,20,{animate:true,duration:2.8});continuousTimer=setTimeout(()=>{if(!continuousActive||continuousIndex%stops.length!==selectedIndex)return;card.innerHTML=`<b>${esc(current.name)} · visão ampliada</b><small>Próxima: ${esc(next.name)} · clique para avançar</small>`;map.flyTo(current.point,17,{animate:true,duration:2});continuousTimer=setTimeout(()=>runContinuousStop(true),5000)},10000)}
