function restoreContinuousAuxLayout(panel,type){if(matchMedia('(max-width:700px)').matches)return;try{let saved=JSON.parse(localStorage.getItem(continuousAuxLayoutKey(type))||'null');if(!saved)return;let maxLeft=Math.max(0,window.innerWidth-180),maxTop=Math.max(0,window.innerHeight-120);panel.style.left=`${Math.max(0,Math.min(maxLeft,Number(saved.left)||0))}px`;panel.style.top=`${Math.max(0,Math.min(maxTop,Number(saved.top)||0))}px`;panel.style.right='auto';panel.style.bottom='auto';panel.style.transform='none';if(Number(saved.width)>=260)panel.style.width=`${Math.min(window.innerWidth-16,Number(saved.width))}px`;if(Number(saved.height)>=190)panel.style.height=`${Math.min(window.innerHeight-16,Number(saved.height))}px`}catch(_){}}
function enableContinuousAuxDrag(panel,type){if(matchMedia('(max-width:700px)').matches)return;let handle=panel.querySelector('.continuous-aux-title'),drag=null;if(!handle)return;handle.onpointerdown=event=>{if(event.button!==undefined&&event.button!==0)return;event.preventDefault();let box=panel.getBoundingClientRect();drag={x:event.clientX,y:event.clientY,left:box.left,top:box.top};panel.style.left=`${box.left}px`;panel.style.top=`${box.top}px`;panel.style.right='auto';panel.style.bottom='auto';panel.style.transform='none';handle.setPointerCapture?.(event.pointerId)};handle.onpointermove=event=>{if(!drag)return;let maxLeft=Math.max(0,window.innerWidth-panel.offsetWidth),maxTop=Math.max(0,window.innerHeight-panel.offsetHeight);panel.style.left=`${Math.max(0,Math.min(maxLeft,drag.left+event.clientX-drag.x))}px`;panel.style.top=`${Math.max(0,Math.min(maxTop,drag.top+event.clientY-drag.y))}px`};let finish=event=>{if(!drag)return;drag=null;handle.releasePointerCapture?.(event.pointerId);saveContinuousAuxLayout(panel,type)};handle.onpointerup=finish;handle.onpointercancel=finish}
function createContinuousAux(type){if(!continuousActive||continuousAux[type].map)return;if(matchMedia('(max-width:700px)').matches){for(let other of ['dedicated','pops','links'])if(other!==type&&continuousAux[other].map){localStorage.setItem(`netatlas_continuous_${other}`,'0');destroyContinuousAux(other)}}let titles={dedicated:'Clientes dedicados',pops:'POPs',links:'Enlaces'},icons={dedicated:'▦',pops:'◎',links:'⇄'},title=titles[type],icon=icons[type],mode=type==='dedicated'?`<select class="continuous-aux-mode" title="Modo de visualização"><option value="sequence">Um por vez</option><option value="overview">Mostrar todos</option></select>`:'';document.body.insertAdjacentHTML('beforeend',`<section id="continuousAux-${type}" class="continuous-aux ${type}"><div class="continuous-aux-map"></div><span class="continuous-aux-title">${icon} ${title}</span>${mode}<button class="continuous-aux-close" title="Fechar painel">×</button><div class="continuous-aux-info"></div></section>`);let panel=document.getElementById(`continuousAux-${type}`);restoreContinuousAuxLayout(panel,type);let auxMap=L.map(panel.querySelector('.continuous-aux-map'),{zoomControl:false,attributionControl:false,preferCanvas:true,fadeAnimation:false,zoomAnimation:true}).setView(map.getCenter(),map.getZoom());L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,maxNativeZoom:19}).addTo(auxMap);let state=continuousAux[type];state.map=auxMap;state.layer=L.layerGroup().addTo(auxMap);state.observer=new ResizeObserver(()=>requestAnimationFrame(()=>{state.map?.invalidateSize({pan:false});saveContinuousAuxLayout(panel,type)}));state.observer.observe(panel);enableContinuousAuxDrag(panel,type);panel.querySelector('.continuous-aux-close').onclick=()=>{localStorage.setItem(`netatlas_continuous_${type}`,'0');destroyContinuousAux(type)};let selector=panel.querySelector('.continuous-aux-mode');if(selector){selector.value=localStorage.getItem('netatlas_continuous_dedicated_mode')||'sequence';selector.onchange=()=>{localStorage.setItem('netatlas_continuous_dedicated_mode',selector.value);state.index=0;runDedicatedPanel()}}let dock=document.getElementById(`continuousAuxDock-${type}`);if(dock)dock.hidden=true;setTimeout(()=>{if(!state.map)return;auxMap.invalidateSize({pan:false});if(type==='dedicated')runDedicatedPanel();else if(type==='pops')runPopsAux();else runLinksAux()},50+({dedicated:0,pops:350,links:700}[type]||0))}
document.getElementById('continuousButton').onclick=startContinuousView;

function activeNetworkAlerts(){let alerts=currentIssues.filter(issue=>issue.status!=='resolved').map(issue=>({key:`issue:${issue.id}`,title:`${issueLabel(issue.severity)} · ${issue.target_name}`,detail:issue.description}));for(let link of links.filter(item=>item.status==='down'))alerts.push({key:`link:${link.id}:down`,title:`Enlace offline · ${link.name}`,detail:`${link.source_name} → ${link.target_name}`});for(let marker of [...markers.values()].filter(item=>item.net.kind==='dedicated'&&dedicatedStatus(item.net.id)==='down')){let metric=dedicatedMetrics.get(Number(marker.net.id));alerts.push({key:`dedicated:${marker.net.id}:down`,title:`Cliente dedicado offline · ${marker.net.name}`,detail:`ICMP ping retornou 0${metric?.loss_percent!=null?` · perda ${Number(metric.loss_percent).toLocaleString('pt-BR',{maximumFractionDigits:2})}%`:''}`})}return alerts}
let criticalAlertTimer=null,criticalAlertDeadlines=new Map(),minimizedAlertKeys=new Set(),dismissedAlertKeys=new Set();
async function updateCriticalAlerts(){if(!netUser||alertUpdateRunning)return;alertUpdateRunning=true;try{let alerts=activeNetworkAlerts(),activeKeys=new Set(alerts.map(alert=>alert.key));for(let key of [...criticalAlertDeadlines.keys()])if(!activeKeys.has(key))criticalAlertDeadlines.delete(key);for(let set of [minimizedAlertKeys,dismissedAlertKeys])for(let key of [...set])if(!activeKeys.has(key))set.delete(key);let acked=new Set();if(canReport()){let response=await api('/api/alert-acknowledgements/sync',{method:'POST',body:JSON.stringify({active_keys:[...activeKeys]})});acked=new Set(response.acknowledged||[])}for(let key of acked)minimizedAlertKeys.add(key);let pending=alerts.filter(alert=>!minimizedAlertKeys.has(alert.key)),minimized=alerts.filter(alert=>minimizedAlertKeys.has(alert.key)&&!dismissedAlertKeys.has(alert.key));document.getElementById('criticalAlert')?.remove();document.getElementById('criticalMini')?.remove();document.getElementById('ackAlertBar')?.remove();clearTimeout(criticalAlertTimer);criticalAlertTimer=null;if(pending.length){let alert=pending[0],deadline=criticalAlertDeadlines.get(alert.key)||Date.now()+60000;criticalAlertDeadlines.set(alert.key,deadline);let remaining=Math.max(0,deadline-Date.now()),actions=canReport()?'<button id="ackCriticalAlert">Reconhecer alerta</button><span>O alerta será recolhido automaticamente.</span>':'<span>O alerta será recolhido automaticamente.</span>';document.body.insertAdjacentHTML('beforeend',`<div id="criticalAlert" class="critical-alert"><b>${esc(alert.title)}</b><small>${esc(alert.detail||'Atenção necessária na rede.')}${pending.length>1?` · mais ${pending.length-1} alerta${pending.length===2?'':'s'}`:''}</small><div class="critical-alert-actions">${actions}</div><svg class="critical-countdown" viewBox="0 0 32 32" style="--duration:${remaining}ms" title="Recolher em um minuto"><circle class="critical-countdown-track" cx="16" cy="16" r="14"></circle><circle class="critical-countdown-progress" cx="16" cy="16" r="14"></circle></svg></div>`);let acknowledge=document.getElementById('ackCriticalAlert');if(acknowledge)acknowledge.onclick=async()=>{await api('/api/alert-acknowledgements',{method:'POST',body:JSON.stringify({alert_key:alert.key})});minimizedAlertKeys.add(alert.key);criticalAlertDeadlines.delete(alert.key);updateCriticalAlerts()};criticalAlertTimer=setTimeout(()=>{minimizedAlertKeys.add(alert.key);criticalAlertDeadlines.delete(alert.key);updateCriticalAlerts()},remaining)}if(minimized.length){let alert=minimized[0];document.body.insertAdjacentHTML('beforeend',`<div id="criticalMini" class="critical-mini"><button id="closeCriticalMini" class="critical-mini-close" title="Fechar aviso">×</button><b>⚠ ${esc(alert.title)}</b><small>${esc(alert.detail||'Alerta ativo no mapa.')}${minimized.length>1?` · mais ${minimized.length-1}`:''}</small></div>`);document.getElementById('closeCriticalMini').onclick=()=>{for(let item of minimized)dismissedAlertKeys.add(item.key);document.getElementById('criticalMini')?.remove()}}}finally{alertUpdateRunning=false}}
async function openCtoDialog(m){closePanel();showLinkDialog(`<div id="ctoDialogBody" class="cto-dialog-body"><div class="cto-dialog-hero"><span class="cto-dialog-icon">◇</span><div><h2>${esc(m.net.name)}</h2><small>CTO · distribuição óptica, portas do splitter e clientes</small></div></div><div class="panel-meta">Carregando estrutura da CTO…</div></div>`);await appendCtoDistribution(m);let body=document.getElementById('ctoDialogBody'),actions=document.createElement('div');actions.className='cto-dialog-actions';if(canOperate()){let remove=document.createElement('button');remove.className='panel-action danger';remove.textContent='Excluir CTO';remove.onclick=()=>deleteCtoConfirmed(m);actions.append(remove)}if(canReport()){let report=document.createElement('button');report.className='panel-action';report.textContent='Reportar erro';report.onclick=()=>openIssueForm({kind:'node',id:m.net.id,name:m.net.name});actions.append(report)}body.append(actions);activeMetricsPanel=null}
openHostPanel=async function(m){if(m.net.kind==='cto'){await openCtoDialog(m);return}if(m.net.kind==='cloud'){openOperatorCloud(m);return}if(m.net.kind==='dedicated'){await openDedicatedClient(m);return}await originalOpenHostPanel(m);if((m.net.kind==='device'||m.net.kind==='host')&&canOperate()&&!document.getElementById('provisionalHostLink')){let provisional=document.createElement('button');provisional.id='provisionalHostLink';provisional.className='panel-action';provisional.textContent='Criar enlace provisório';provisional.onclick=()=>beginLink(m,null);document.getElementById('panelBody').append(provisional)}if(m.net.kind==='device'){await appendBgpPanel(m);await appendOperatorToggle(m)}if(m.net.kind==='host'&&canOperate()){let b=document.createElement('button');b.id='validateProvisionalHost';b.className='panel-action';b.textContent='Validar com host do Zabbix';b.onclick=()=>validateProvisionalHost(m);document.getElementById('panelBody').append(b)}if(m.net.kind==='device'&&canOperate()){let b=document.createElement('button');b.id='deleteHost';b.className='panel-action danger';b.textContent='Excluir Host';b.onclick=()=>deleteHostConfirmed(m);document.getElementById('panelBody').append(b)}reportButton({kind:m.net.kind==='device'?'device':'node',id:m.net.id,name:m.net.name});activeMetricsPanel=m.net.kind==='device'?{kind:'host',markerKey:`device:${m.net.id}`} :null};
const originalOpenLinkPanel=openLinkPanel;
openLinkPanel=async function(l,layer,clickedLatLng=null){let issuePoint=clickedLatLng||l._clickedLatLng||activeMetricsPanel?.clickedLatLng;await originalOpenLinkPanel(l,layer,issuePoint);if(netUser.role!=='superadmin'){let del=document.getElementById('deleteLink');if(del)del.remove()}if(!canOperate()){for(let id of ['editLink','renameLink','replaceSourceInterface','replaceTargetInterface','insertCtoInLink','validateSuggestedRoute']){let button=document.getElementById(id);if(button)button.remove()}}reportButton({kind:'link',id:l.id,name:l.name,latitude:issuePoint?.lat,longitude:issuePoint?.lng});activeMetricsPanel={kind:'link',id:Number(l.id),clickedLatLng:issuePoint}};
const originalClosePanel=closePanel;
closePanel=function(){activeMetricsPanel=null;originalClosePanel()};

function roadPointKey(p){return`${Number(p[0]).toFixed(5)},${Number(p[1]).toFixed(5)}`}
function roadSegmentKey(a,b){let x=roadPointKey(a),y=roadPointKey(b);return x<y?`${x}|${y}`:`${y}|${x}`}
function laneNumber(index,count){return index-(count-1)/2}
function linkWeight(){let z=map.getZoom();return z<=11?1.5:z===12?2:z===13?3:z===14?4:5}
function ponInterface(name){return/(?:^|\s)(?:XGS?-?PON|GPON|PON)\s*[-:]?\s*\d+\/\d+\/\d+/i.test(name||'')}
function ponFlowCoordinates(link,coordinates){let sourcePon=ponInterface(link.source_interface_name),targetPon=ponInterface(link.target_interface_name);if(!sourcePon&&!targetPon)return null;return targetPon&&!sourcePon?[...coordinates].reverse():coordinates}
function isDedicatedLink(link){return(link.source_kind==='node'&&markers.get(`dedicated:${link.source_id}`))||(link.target_kind==='node'&&markers.get(`dedicated:${link.target_id}`))}
function separatedCoordinates(link,segments){let cs=link.geometry.coordinates.map(p=>[Number(p[0]),Number(p[1])]);if(cs.length<2)return cs;let offsets=cs.map(()=>({x:0,y:0,n:0})),spacing=linkWeight()+2;for(let i=0;i<cs.length-1;i++){let group=segments.get(roadSegmentKey(cs[i],cs[i+1]))||[link],ordered=[...group].sort((a,b)=>Number(a.id)-Number(b.id)),lane=laneNumber(ordered.findIndex(x=>Number(x.id)===Number(link.id)),ordered.length);if(!lane)continue;let a=map.latLngToLayerPoint([cs[i][1],cs[i][0]]),b=map.latLngToLayerPoint([cs[i+1][1],cs[i+1][0]]),dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy);if(!n)continue;let ox=-dy/n*lane*spacing,oy=dx/n*lane*spacing;for(let j of [i,i+1]){offsets[j].x+=ox;offsets[j].y+=oy;offsets[j].n++}}return cs.map((p,i)=>{let o=offsets[i];if(!o.n)return p;let base=map.latLngToLayerPoint([p[1],p[0]]),ll=map.layerPointToLatLng([base.x+o.x/o.n,base.y+o.y/o.n]);return[ll.lng,ll.lat]})}
function pointSegmentDistance(p,a,b){let dx=b.x-a.x,dy=b.y-a.y;if(!dx&&!dy)return p.distanceTo(a);let t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy))),x=a.x+t*dx,y=a.y+t*dy;return Math.hypot(p.x-x,p.y-y)}
function linksNear(latlng,fallback){let p=map.latLngToLayerPoint(latlng),base=fallback.display_coordinates||fallback.geometry.coordinates,best={distance:Infinity,a:null,b:null};for(let i=1;i<base.length;i++){let a=map.latLngToLayerPoint([base[i-1][1],base[i-1][0]]),b=map.latLngToLayerPoint([base[i][1],base[i][0]]),distance=pointSegmentDistance(p,a,b);if(distance<best.distance)best={distance,a,b}}let bdx=best.b.x-best.a.x,bdy=best.b.y-best.a.y,bn=Math.hypot(bdx,bdy)||1;return links.filter(l=>!(l.trunk_group&&!l.is_trunk)).filter(l=>{let cs=l.display_coordinates||l.geometry.coordinates;for(let i=1;i<cs.length;i++){let a=map.latLngToLayerPoint([cs[i-1][1],cs[i-1][0]]),b=map.latLngToLayerPoint([cs[i][1],cs[i][0]]),dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy)||1,parallel=Math.abs((dx*bdx+dy*bdy)/(n*bn));if(parallel>=.94&&pointSegmentDistance(p,a,b)<=24)return true}return false}).sort((a,b)=>Number(a.id)-Number(b.id))}
function chooseLinkAt(latlng,fallback){let nearby=linksNear(latlng,fallback);if(!nearby.some(link=>Number(link.id)===Number(fallback.id)))nearby.push(fallback);nearby.sort((a,b)=>Number(a.id)-Number(b.id));if(nearby.length<2){let layer=linkLayers.get(Number(fallback.id));if(layer)openLinkPanel(fallback,layer,latlng);return}let popup=L.popup({maxWidth:360}).setLatLng(latlng).setContent(`<div class="link-menu"><b>${nearby.length} enlaces neste trecho</b>${nearby.map(l=>`<button class="choose-overlap-link" data-id="${l.id}"><span class="${l.status==='up'?'updot':l.status==='down'?'downdot':'unkdot'}">●</span> ${esc(l.name)}${l.is_trunk?'<br><small>Eth-Trunk</small>':l.route_mode==='suggested'?'<br><small>Trajeto sugerido</small>':''}</button>`).join('')}</div>`).openOn(map);setTimeout(()=>document.querySelectorAll('.choose-overlap-link').forEach(b=>b.onclick=()=>{let l=links.find(x=>Number(x.id)===Number(b.dataset.id)),layer=linkLayers.get(Number(b.dataset.id));map.closePopup(popup);if(l&&layer)openLinkPanel(l,layer,latlng)}),0)}
function renderLinks(){
 editable.clearLayers();suggestedBorders.clearLayers();ponFlowLayers.clearLayers();linkLayers.clear();
 let visibleLinks=links.filter(l=>!(l.trunk_group&&!l.is_trunk)),segments=new Map(),weight=linkWeight();
 visibleLinks.forEach(l=>{let cs=l.geometry.coordinates;for(let i=1;i<cs.length;i++){let key=roadSegmentKey(cs[i-1],cs[i]);if(!segments.has(key))segments.set(key,[]);segments.get(key).push(l)}});
 visibleLinks.filter(l=>l.is_trunk&&l.trunk_group).forEach(trunk=>{let latlngs=trunk.geometry.coordinates.map(p=>[p[1],p[0]]);L.polyline(latlngs,{color:'#111827',weight:weight+6,opacity:.78,interactive:false,className:'eth-trunk-sleeve'}).addTo(suggestedBorders)});
 visibleLinks.forEach(l=>{
  let display=separatedCoordinates(l,segments),latlngs=display.map(p=>[p[1],p[0]]);l.display_coordinates=display;
  if(l.route_mode==='suggested')L.polyline(latlngs,{color:'#0284c7',weight:weight+4,opacity:.95,interactive:false,className:'suggested-route-border'}).addTo(suggestedBorders);
  let dedicated=Boolean(isDedicatedLink(l)),state=l.status==='up'?'up':l.status==='down'?'down':l.status==='provisional'?'provisional':'unknown',layer=L.polyline(latlngs,{color:lineColor(l.status),weight,className:`net-link net-link-${state} ${l.is_trunk?'eth-trunk-main':''} ${dedicated?'dedicated-access-link':''}`,bubblingMouseEvents:false});layer.linkId=l.id;linkLayers.set(Number(l.id),layer);layer.on('click',e=>chooseLinkAt(e.latlng,l));layer.on('contextmenu',e=>{if(e.originalEvent)L.DomEvent.preventDefault(e.originalEvent);if(mode)return;let popup=L.popup({closeButton:true}).setLatLng(e.latlng).setContent(`<div class="link-menu"><b>${esc(l.name)}</b>${l.is_trunk?'<small>Eth-Trunk</small>':l.route_mode==='suggested'?'<small>Trajeto sugerido</small>':''}${ponInterface(l.source_interface_name)||ponInterface(l.target_interface_name)?'<small>Fibra GPON</small>':dedicated?'<small>Acesso dedicado</small>':''}<button id="openLinkDetails">Abrir detalhes</button><button id="removeLinkHere" class="danger">Excluir enlace</button></div>`).openOn(map);setTimeout(()=>{let open=document.getElementById('openLinkDetails'),remove=document.getElementById('removeLinkHere');if(open)open.onclick=()=>{map.closePopup(popup);openLinkPanel(l,layer,e.latlng)};if(remove)remove.onclick=()=>{map.closePopup(popup);deleteLinkConfirmed(l)}},0)});editable.addLayer(layer);
  let flow=ponFlowCoordinates(l,display);if(flow){let flowLatLngs=flow.map(p=>[p[1],p[0]]);L.polyline(flowLatLngs,{color:'#e0f2fe',weight:Math.max(.8,Math.min(1.5,weight*.3)),opacity:.9,interactive:false,className:`pon-fiber-flow pon-fiber-flow-${state}`,pane:'overlayPane'}).addTo(ponFlowLayers)}
  else if(dedicated)L.polyline(latlngs,{color:state==='down'?'#fecaca':state==='up'?'#7dd3fc':'#64748b',weight:Math.max(1,Math.min(2,weight*.38)),opacity:.95,interactive:false,className:`dedicated-access-flow dedicated-access-flow-${state}`,pane:'overlayPane'}).addTo(ponFlowLayers)
 })
}
loadLinks=async function(){links=await api('/api/links');renderLinks();updateDedicatedMarkers();updateCriticalAlerts().catch(()=>{})};
map.on('zoomend',()=>{if(!mode&&!document.querySelector('.leaflet-editing-icon')&&links.length)renderLinks()});

function openIssueForm(target){if(!canReport()){flashHint('O perfil Visualização não pode reportar erros.',4000);return}let coordinate=target.kind==='link'&&Number.isFinite(target.latitude)&&Number.isFinite(target.longitude)?`<div class="issue-card"><small>Ponto selecionado no enlace</small><br><b>${target.latitude.toFixed(6)}, ${target.longitude.toFixed(6)}</b></div>`:'';modal('Reportar erro',`<form id="issueForm"><p><b>${esc(target.name)}</b></p>${coordinate}<label>Classificação</label><select id="issueSeverity"><option value="medium">Médio — amarelo</option><option value="severe">Grave — laranja</option><option value="disaster">Desastre — vermelho</option></select><label>Descrição breve</label><textarea id="issueDescription" maxlength="1000" required style="width:100%;min-height:95px;background:#091526;color:#fff;border:1px solid #38506f;border-radius:6px;padding:9px"></textarea><p id="issueError" class="form-error"></p><button class="primary" type="submit">Reportar erro</button></form>`);document.getElementById('issueForm').onsubmit=async e=>{e.preventDefault();try{let result=await api('/api/issues',{method:'POST',body:JSON.stringify({target_kind:target.kind,target_id:target.id,target_name:target.name,severity:document.getElementById('issueSeverity').value,description:document.getElementById('issueDescription').value.trim(),latitude:target.latitude??null,longitude:target.longitude??null})});closeModal();await loadIssues(false);hint(result.status==='pending'?'Erro enviado para validação.':'Erro registrado e validado.')}catch(x){document.getElementById('issueError').textContent=x.message}}};
function issueRank(s){return s==='disaster'?3:s==='severe'?2:1}
function badgeFor(issue){let isX=issue.status!=='pending'&&issue.severity==='disaster',symbol=issue.status==='pending'?'?':isX?'':'!';return L.divIcon({className:'',iconSize:[24,24],iconAnchor:[12,12],html:`<div class="issue-badge issue-${issue.severity} ${isX?'issue-x':''}">${symbol}</div>`})}
function issueLabel(value){return({medium:'Médio',severe:'Grave',disaster:'Desastre',pending:'Pendente de validação',validated:'Validado',resolved:'Resolvido'})[value]||value}
function showIssueDetails(issue){let coordinate=issue.latitude!=null&&issue.longitude!=null?`<br><b>Coordenada:</b> ${Number(issue.latitude).toFixed(6)}, ${Number(issue.longitude).toFixed(6)}`:'';modal('Detalhes do erro',`<div class="issue-card"><h3>${esc(issue.target_name)}</h3><p><b>Classificação:</b> ${esc(issueLabel(issue.severity))}<br><b>Status:</b> ${esc(issueLabel(issue.status))}<br><b>Reportado por:</b> ${esc(issue.reported_by_name)}${issue.validated_by_name?`<br><b>Validado por:</b> ${esc(issue.validated_by_name)}`:''}${coordinate}</p><p>${esc(issue.description)}</p><small>Registrado em ${new Date(issue.created_at).toLocaleString('pt-BR')}</small>${issue.status==='pending'&&canOperate()?`<button id="detailValidate" class="panel-action">Validar erro</button>`:''}${issue.status!=='resolved'&&canOperate()?`<button id="detailResolve" class="panel-action">Marcar como resolvido</button>`:''}</div>`);let validate=document.getElementById('detailValidate'),resolve=document.getElementById('detailResolve');if(validate)validate.onclick=async()=>{await api(`/api/issues/${issue.id}/validate`,{method:'POST'});closeModal();await loadIssues(false);hint('Erro validado.')} ;if(resolve)resolve.onclick=async()=>{await api(`/api/issues/${issue.id}/resolve`,{method:'POST'});closeModal();await loadIssues(false);hint('Erro marcado como resolvido.')}}
function linkMidpoint(cs){if(!cs||!cs.length)return null;if(cs.length===1)return L.latLng(cs[0][1],cs[0][0]);let segments=[],total=0;for(let i=1;i<cs.length;i++){let a=L.latLng(cs[i-1][1],cs[i-1][0]),b=L.latLng(cs[i][1],cs[i][0]),length=map.distance(a,b);segments.push({a,b,length});total+=length}let wanted=total/2,walked=0;for(let s of segments){if(walked+s.length>=wanted){let t=s.length?(wanted-walked)/s.length:0;return L.latLng(s.a.lat+(s.b.lat-s.a.lat)*t,s.a.lng+(s.b.lng-s.a.lng)*t)}walked+=s.length}let last=cs[cs.length-1];return L.latLng(last[1],last[0])}
function nearestPop(point,maxMeters=1500){let best=null;for(let marker of siteMarkers){let distance=map.distance(point,marker.getLatLng());if(distance<=maxMeters&&(!best||distance<best.distance))best={marker,distance}}return best}
function linkPixelLength(link){let coordinates=link.display_coordinates||link.geometry.coordinates,total=0;for(let i=1;i<coordinates.length;i++)total+=map.latLngToContainerPoint([coordinates[i-1][1],coordinates[i-1][0]]).distanceTo(map.latLngToContainerPoint([coordinates[i][1],coordinates[i][0]]));return total}
function refreshPopAndNetworkAlerts(){networkAlertMarkers.forEach(marker=>map.removeLayer(marker));networkAlertMarkers=[];let popView=map.getZoom()<=15,alerts=new Map(),setAlert=(marker,severity)=>{let old=alerts.get(marker),rank=value=>value==='disaster'?3:value==='severe'?2:1;if(!old||rank(severity)>rank(old))alerts.set(marker,severity)};if(popView)for(let badge of issueMarkers){let near=nearestPop(badge.getLatLng());if(near)setAlert(near.marker,badge.issue.severity)}for(let link of links.filter(item=>item.status==='down')){if(linkPixelLength(link)>=45)continue;let point=linkMidpoint(link.display_coordinates||link.geometry.coordinates),near=popView&&point?nearestPop(point):null;if(near){setAlert(near.marker,'disaster');continue}if(point){let marker=L.marker(point,{icon:badgeFor({severity:'disaster',status:'validated'}),interactive:true,zIndexOffset:2100});marker.on('click',()=>{let layer=linkLayers.get(Number(link.id));if(layer)openLinkPanel(link,layer,point)});marker.addTo(map);networkAlertMarkers.push(marker)}}for(let client of [...markers.values()].filter(item=>item.net.kind==='dedicated'&&dedicatedStatus(item.net.id)==='down')){let point=client.getLatLng(),near=popView?nearestPop(point):null;if(near){setAlert(near.marker,'disaster');continue}let badge=L.marker(point,{icon:badgeFor({severity:'disaster',status:'validated'}),interactive:true,zIndexOffset:2150});badge.on('click',()=>openDedicatedClient(client));badge.addTo(map);networkAlertMarkers.push(badge)}siteMarkers.forEach(marker=>marker.setIcon(popMarkerIcon(marker.net,alerts.get(marker)||null)))}
function refreshIssueVisibility(){let popView=map.getZoom()<=15;issueMarkers.forEach(b=>{let hide=Boolean(popView&&nearestPop(b.getLatLng()));if(hide){if(map.hasLayer(b))map.removeLayer(b)}else if(!map.hasLayer(b))b.addTo(map)});refreshPopAndNetworkAlerts()}
function refreshIssueMarkers(issues){issueMarkers.forEach(m=>map.removeLayer(m));issueMarkers=[];let selected=new Map();issues.filter(i=>i.status!=='resolved').forEach(i=>{let k=`${i.target_kind}:${i.target_id}`,old=selected.get(k);if(!old||issueRank(i.severity)>issueRank(old.severity)||i.status==='pending'&&old.status!=='pending')selected.set(k,i)});selected.forEach(i=>{let point=null;if(i.target_kind==='link'){if(i.latitude!=null&&i.longitude!=null)point=L.latLng(Number(i.latitude),Number(i.longitude));else{let l=links.find(x=>Number(x.id)===Number(i.target_id));if(l)point=linkMidpoint(l.display_coordinates||l.geometry.coordinates)}}else{let m=markers.get(`${i.target_kind==='node'?'cto':'device'}:${i.target_id}`)||markers.get(`host:${i.target_id}`);if(m)point=m.getLatLng()}if(point){let b=L.marker(point,{icon:badgeFor(i),interactive:true,zIndexOffset:2000});b.issue=i;b.on('click',e=>{if(e.originalEvent)L.DomEvent.stopPropagation(e.originalEvent);showIssueDetails(i)});b.addTo(map);issueMarkers.push(b)}});refreshIssueVisibility()}
async function loadIssues(notify=true){let issues=await api('/api/issues');currentIssues=issues;let open=issues.filter(i=>i.status!=='resolved'),pending=open.filter(i=>i.status==='pending');document.getElementById('issueCount').textContent=open.length;document.getElementById('issuesButton').title=`${open.length} erro${open.length===1?'':'s'} aberto${open.length===1?'':'s'}`;refreshIssueMarkers(issues);if(notify&&['admin','superadmin'].includes(netUser.role)){let fresh=pending.filter(i=>!seenPending.has(i.id));if(fresh.length)showIssueInbox(pending)}pending.forEach(i=>seenPending.add(i.id));updateCriticalAlerts().catch(()=>{});return issues}
async function showIssueInbox(items=null){items=items||await api('/api/issues');let open=items.filter(i=>i.status!=='resolved');modal('Erros da rede',`<div class="issue-list">${open.map(i=>`<div class="issue-card"><b class="${i.severity==='medium'?'unkdot':i.severity==='severe'?'': 'downdot'}">${esc(i.target_name)} · ${esc(i.severity)}</b><p>${esc(i.description)}</p><small>${esc(i.reported_by_name)} · ${esc(i.status)}</small>${i.status==='pending'&&canOperate()?`<button class="validateIssue" data-id="${i.id}">Validar</button>`:''}${i.status!=='resolved'&&canOperate()?`<button class="resolveIssue" data-id="${i.id}">Resolver</button>`:''}</div>`).join('')||'<p>Nenhum erro aberto.</p>'}</div>`);document.querySelectorAll('.validateIssue').forEach(b=>b.onclick=async()=>{await api(`/api/issues/${b.dataset.id}/validate`,{method:'POST'});await showIssueInbox(await loadIssues(false))});document.querySelectorAll('.resolveIssue').forEach(b=>b.onclick=async()=>{await api(`/api/issues/${b.dataset.id}/resolve`,{method:'POST'});await showIssueInbox(await loadIssues(false))})}
document.getElementById('issuesButton').onclick=()=>showIssueInbox();
function licenseMessage(l){if(!l.configured)return'<p>Nenhuma chave foi ativada neste NetAtlas.</p>';if(l.valid)return`<p class="updot"><b>Licença válida</b></p><p>Chave: ${esc(l.license_key)}<br>Verificada: ${l.last_checked_at?new Date(l.last_checked_at).toLocaleString('pt-BR'):'agora'}${l.details?.expires_at?`<br>Expira em: ${esc(new Date(l.details.expires_at).toLocaleDateString('pt-BR'))}`:''}${l.details?.days_remaining!=null?` · ${esc(l.details.days_remaining)} dias restantes`:''}</p>`;return`<p class="downdot"><b>Licença não validada</b></p><p>${esc(l.details?.reason||'Verifique a chave e a conexão com o servidor de licenças.')}</p>`}
async function showLicense(required=false){let l=await api('/api/license');modal('Licença · LVL - NetAtlas',`${required?'<p class="downdot"><b>É necessário ativar uma licença válida para utilizar esta instalação.</b></p>':''}${licenseMessage(l)}<form id="licenseForm"><label>Chave de licença</label><input id="licenseKey" required autocomplete="off" placeholder="Cole a chave aqui"><p id="licenseError" class="form-error"></p><button class="primary" type="submit">Ativar e validar</button>${l.configured?'<button id="licenseRecheck" type="button">Validar novamente</button>':''}</form>`);if(required){let cancel=document.querySelector('#modal>.box>button');if(cancel)cancel.style.display='none'}document.getElementById('licenseForm').onsubmit=async e=>{e.preventDefault();let error=document.getElementById('licenseError');error.textContent='Validando…';try{await api('/api/license/activate',{method:'POST',body:JSON.stringify({license_key:document.getElementById('licenseKey').value})});required?location.reload():(closeModal(),hint('Licença ativada e validada com sucesso.'))}catch(x){error.textContent=x.message}};let check=document.getElementById('licenseRecheck');if(check)check.onclick=async()=>{try{await api('/api/license/check',{method:'POST'});required?location.reload():(closeModal(),hint('Licença validada com sucesso.'))}catch(x){document.getElementById('licenseError').textContent=x.message}}}
document.getElementById('licenseButton').onclick=()=>showLicense().catch(e=>hint(e.message));
async function showUpdates(){modal('Atualizações do NetAtlas','<p class="muted">Consultando o repositório oficial no GitHub…</p>');try{let data=await api('/api/update/status'),short=value=>(value||'—').slice(0,7),changes=data.commits||[],state=data.available?'Nova atualização disponível':data.local_ahead?'Versão local ainda não publicada no GitHub':'NetAtlas atualizado';document.getElementById('modalBody').innerHTML=`<div class="issue-card"><b>${state}</b><p>Instalada: <code>${esc(short(data.current))}</code><br>GitHub: <code>${esc(short(data.latest))}</code></p>${data.local_ahead?'<p class="muted">Esta instalação possui alterações mais novas que o repositório remoto.</p>':changes.length?`<details><summary>Ver alterações (${changes.length})</summary>${changes.map(change=>`<p><code>${esc(change.sha)}</code> · ${esc(change.message)}</p>`).join('')}</details>`:'<p class="muted">Não há alterações pendentes.</p>'}</div><p id="updateError" class="form-error"></p>${data.available?'<button id="applyNetAtlasUpdate" class="primary">Baixar e instalar atualização</button>':''}`;let apply=document.getElementById('applyNetAtlasUpdate');if(apply)apply.onclick=async()=>{let confirmed=await confirmForm('Instalar atualização','A aplicação será atualizada pelo GitHub e reiniciada. O mapa poderá ficar indisponível por alguns segundos.','Instalar agora');if(!confirmed)return;modal('Atualizando NetAtlas','<p>Baixando a atualização e reiniciando o serviço…</p><p class="muted">Esta página será recarregada automaticamente.</p>');try{await api('/api/update/apply',{method:'POST',body:'{}'});setTimeout(()=>location.reload(),15000)}catch(error){document.getElementById('modalBody').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}}catch(error){document.getElementById('modalBody').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}
document.getElementById('updateButton').onclick=()=>showUpdates();
async function showAuditLog(){let events=await api('/api/audit?limit=300');modal('Log de ações',`<div class="issue-list">${events.map(x=>`<div class="issue-card"><b>${esc(x.action)}</b><br><small>${esc(x.actor_username)} · ${esc(x.actor_role)} · ${new Date(x.created_at).toLocaleString('pt-BR')}</small><p>${esc(x.target_kind)}${x.target_name?` · ${esc(x.target_name)}`:x.target_id?` #${esc(x.target_id)}`:''}</p>${x.details&&Object.keys(x.details).length?`<small>${esc(Object.entries(x.details).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' · '))}</small>`:''}</div>`).join('')||'<p>Nenhuma alteração registrada ainda.</p>'}</div>`)}
document.getElementById('auditButton').onclick=()=>showAuditLog().catch(e=>hint(e.message));
function userRoleOptions(){let roles=netUser.role==='superadmin'?[['admin','Admin'],['technician','Técnico'],['viewer','Visualização'],['superadmin','Superadmin']]:[['technician','Técnico'],['viewer','Visualização']];return roles.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}
async function createUserForm(){modal('Criar usuário',`<form id="userForm"><label>Usuário</label><input id="newUsername" required minlength="3"><label>Nome</label><input id="newDisplayName" required><label>Perfil</label><select id="newRole">${userRoleOptions()}</select><label>Senha inicial</label><input id="newPassword" type="password" required minlength="8"><p id="userError" class="form-error"></p><button class="primary" type="submit">Criar usuário</button><button id="backToUsers" type="button">Voltar</button></form>`);document.getElementById('backToUsers').onclick=showUserManagement;document.getElementById('userForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify({username:document.getElementById('newUsername').value,display_name:document.getElementById('newDisplayName').value,role:document.getElementById('newRole').value,password:document.getElementById('newPassword').value})});flashHint('Usuário criado com sucesso.',4000);await showUserManagement()}catch(x){document.getElementById('userError').textContent=x.message}}}
async function editUserForm(user){modal(`Gerenciar usuário · ${esc(user.username)}`,`<form id="editUserForm"><label>Nome exibido</label><input id="editDisplayName" required value="${esc(user.display_name)}"><label>Perfil</label><select id="editRole">${userRoleOptions()}</select><label>Nova senha <small>deixe em branco para manter</small></label><input id="editPassword" type="password" minlength="8" autocomplete="new-password"><label class="iface"><input id="editActive" type="checkbox" style="width:auto;margin:0 8px 0 0" ${user.active?'checked':''}> Usuário ativo</label><p id="editUserError" class="form-error"></p><button class="primary" type="submit">Salvar alterações</button><button id="backToUsers" type="button">Voltar</button></form>`);document.getElementById('editRole').value=user.role;document.getElementById('backToUsers').onclick=showUserManagement;document.getElementById('editUserForm').onsubmit=async event=>{event.preventDefault();let password=document.getElementById('editPassword').value,payload={display_name:document.getElementById('editDisplayName').value.trim(),role:document.getElementById('editRole').value,active:document.getElementById('editActive').checked};if(password)payload.password=password;try{await api(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify(payload)});flashHint('Usuário atualizado com sucesso.',4000);await showUserManagement()}catch(error){document.getElementById('editUserError').textContent=error.message}}}
async function showUserManagement(){let users=await api('/api/users'),counts={technician:users.filter(user=>user.role==='technician').length,viewer:users.filter(user=>user.role==='viewer').length},limit=netUser.role==='admin'?`<p class="muted">Seus usuários: ${counts.technician}/3 Técnicos · ${counts.viewer}/2 Visualização.</p>`:'';modal('Gerenciar usuários',`${limit}<button id="createManagedUser" class="primary">Criar usuário</button><div class="management-list">${users.map(user=>`<div class="management-row"><div><b>${esc(user.display_name)}</b><small>${esc(user.username)} · ${esc(roleName(user.role))} · ${user.active?'Ativo':'Desativado'}</small></div><button class="edit-managed-user" data-id="${user.id}">Gerenciar</button></div>`).join('')}</div>`);document.getElementById('createManagedUser').onclick=createUserForm;document.querySelectorAll('.edit-managed-user').forEach(button=>button.onclick=()=>editUserForm(users.find(user=>Number(user.id)===Number(button.dataset.id))))}
document.getElementById('usersButton').onclick=()=>showUserManagement().catch(error=>hint(error.message));
async function showActiveSessions(){let sessions=await api('/api/sessions');modal('Sessões ativas',`<div class="management-list">${sessions.map(session=>`<div class="management-row"><div><b>${esc(session.display_name)} · ${esc(roleName(session.role))}</b><small>${esc(session.username)} · início ${new Date(session.created_at).toLocaleString('pt-BR')} · expira ${new Date(session.expires_at).toLocaleString('pt-BR')}${session.remote_addr?` · IP ${esc(session.remote_addr)}`:''}</small></div></div>`).join('')||'<p>Nenhuma sessão ativa.</p>'}</div>`)}
document.getElementById('sessionsButton').onclick=()=>showActiveSessions().catch(error=>hint(error.message));

async function showPopManagement(){
 let pops=await api('/api/pops');modal('Gerenciar POPs',`<p class="muted">POPs só podem ser excluídos quando não possuem hosts, CTOs ou outros elementos vinculados no NetBox.</p><div class="management-list">${pops.map(pop=>`<div class="management-row"><div><b>${esc(pop.name)}</b><small>${Number(pop.latitude).toFixed(6)}, ${Number(pop.longitude).toFixed(6)} · ${pop.device_count} elemento${pop.device_count===1?'':'s'}</small></div><button class="danger delete-managed-pop" data-id="${pop.id}" data-name="${esc(pop.name)}" ${pop.device_count?'disabled title="Remova ou mova os elementos primeiro"':''}>Excluir</button></div>`).join('')||'<p>Nenhum POP cadastrado.</p>'}</div><p id="popManagementError" class="form-error"></p>`);
 document.querySelectorAll('.delete-managed-pop').forEach(button=>button.onclick=async()=>{let ok=await confirmForm('Excluir POP',`Deseja excluir definitivamente o POP “${button.dataset.name}”?`,'Excluir POP');if(!ok)return;try{await api(`/api/pops/${button.dataset.id}`,{method:'DELETE'});flashHint(`POP ${button.dataset.name} excluído.`,5000);await loadTopology();await showPopManagement()}catch(error){let target=document.getElementById('popManagementError');if(target)target.textContent=error.message}})
}
async function showHostManagement(){
 let hosts=await api('/api/inventory/hosts');modal('Gerenciar Hosts',`<p class="muted">A exclusão remove o host e suas interfaces do NetBox, libera a licença e também remove enlaces e erros associados.</p><input id="managedHostSearch" autocomplete="off" placeholder="Buscar host ou POP"><div id="managedHostList" class="management-list"></div><p id="hostManagementError" class="form-error"></p>`);let search=document.getElementById('managedHostSearch'),list=document.getElementById('managedHostList');
 function render(){let term=search.value.trim().toLocaleLowerCase('pt-BR'),visible=hosts.filter(host=>`${host.name} ${host.site||''}`.toLocaleLowerCase('pt-BR').includes(term));list.innerHTML=visible.map(host=>`<div class="management-row"><div><b>${esc(host.name)}</b><small>${esc(host.site||'Sem POP')} · ${host.zabbix_hostid?`Zabbix #${host.zabbix_hostid}`:'Host local'} · ${esc(host.status)}</small></div><button class="danger delete-managed-host" data-id="${host.id}" data-name="${esc(host.name)}">Excluir</button></div>`).join('')||'<p>Nenhum host encontrado.</p>';document.querySelectorAll('.delete-managed-host').forEach(button=>button.onclick=async()=>{let ok=await confirmForm('Excluir Host',`Deseja excluir definitivamente o host “${button.dataset.name}”? O host, suas interfaces, enlaces e erros associados serão removidos.`,'Excluir Host');if(!ok)return;try{await api(`/api/devices/${button.dataset.id}`,{method:'DELETE'});hosts=hosts.filter(host=>Number(host.id)!==Number(button.dataset.id));render();await Promise.all([loadTopology(),loadLinks(),loadIssues(false)]);flashHint(`Host ${button.dataset.name} excluído.`,5000)}catch(error){let target=document.getElementById('hostManagementError');if(target)target.textContent=error.message}})}search.oninput=render;render();search.focus()
}
document.getElementById('managePopsButton').onclick=()=>showPopManagement().catch(error=>hint(error.message));
document.getElementById('manageHostsButton').onclick=()=>showHostManagement().catch(error=>hint(error.message));

function safeToRefresh(){return!mode&&!document.querySelector('.leaflet-editing-icon')}
let operationalRefreshRunning=false;
async function refreshOperationalStatus(){if(!safeToRefresh()||operationalRefreshRunning)return;operationalRefreshRunning=true;try{let hostIds=[...new Set([...markers.values()].map(m=>m.net.zabbix_hostid).filter(Boolean).map(Number))];if(hostIds.length){let states=await api(`/api/host-statuses?ids=${hostIds.join(',')}`),byId=new Map(states.map(s=>[Number(s.hostid),s]));for(let m of markers.values()){let hid=Number(m.net.zabbix_hostid),s=byId.get(hid);if(!s)continue;m.net.availability=s.availability;m.net.zabbix_status=s.status;m.net.ips=s.ips;m.net.down=Number(s.availability)===2;m.setIcon(mkIcon(m.net))}}await Promise.all([loadLinks(),loadDedicatedMetrics()]);refreshMarkers()}finally{operationalRefreshRunning=false}}
async function refreshActiveMetrics(){if(!safeToRefresh()||!activeMetricsPanel)return;let selected=activeMetricsPanel;if(selected.kind==='host')return;if(!document.getElementById('linkDialog')?.classList.contains('show'))return;let l=links.find(x=>Number(x.id)===selected.id),layer=null;editable.eachLayer(x=>{if(Number(x.linkId)===selected.id)layer=x});if(l&&layer)await openLinkPanel(l,layer,selected.clickedLatLng)}
map.on('zoomend',renderOntMapClients);
map.on('click',async event=>{if(mode==='dedicated-position'&&pendingDedicatedClient){let client=pendingDedicatedClient;pendingDedicatedClient=null;try{await saveDedicatedClient(client.name,event.latlng)}catch(error){mode='dedicated-position';pendingDedicatedClient=client;flashHint(error.message,6000)}return}if(mode!=='ont-position'||!pendingOntPosition)return;let client=pendingOntPosition;pendingOntPosition=null;try{await api(`/api/cto-clients/${client.assignment_id}/position`,{method:'PATCH',body:JSON.stringify({latitude:event.latlng.lat,longitude:event.latlng.lng})});cancel();await loadOntMapClients();map.setView(event.latlng,Math.max(map.getZoom(),18));flashHint(`ONT ${client.number||client.ont_number} posicionada no mapa.`,5000)}catch(error){mode='ont-position';pendingOntPosition=client;flashHint(error.message,6000)}});
const portalCancel=cancel;cancel=function(){pendingOntPosition=null;pendingOperatorPosition=null;pendingDedicatedClient=null;portalCancel()};
async function refreshOtherInformation(){if(!safeToRefresh())return;await Promise.all([loadIssues(true),loadOperatorCards(),loadOntMapClients()])}
async function startNetAtlas(){let r=await fetch('/api/auth/me');if(!r.ok){showLogin();return}netUser=await r.json();applyRole();let license=await api('/api/license');if(!license.valid){await showLicense(true);return}await Promise.all([loadTopology(),loadLinks()]);await Promise.all([loadIssues(true),loadOperatorCards(),loadOntMapClients(),loadDedicatedMetrics()]);setInterval(()=>refreshOperationalStatus().catch(e=>hint(e.message)),30000);setInterval(()=>refreshActiveMetrics().catch(e=>hint(e.message)),120000);setInterval(()=>refreshOtherInformation().catch(e=>hint(e.message)),180000)}
